use vstd::prelude::*;

verus! {
    ///////// vstack //////////////////////////////////////////////////////////
    // Stack two length‐equal float‐vectors into a 2×N matrix.
    fn vstack(a: Vec<f32>, b: Vec<f32>) -> (result: Vec<Vec<f32>>)
        requires
            a.len() == b.len(),
        ensures
            // exactly two rows
            result.len() == 2
            // row lengths match
            && result[0].len() == a.len()
            && result[1].len() == b.len()
            // element‐wise correspondence
            && forall |i: usize|
                 i < a.len() ==>
                    result[0][i] == a[i]
            && forall |i: usize|
                 i < b.len() ==>
                    result[1][i] == b[i]
    {
        // start from empty Vec<Vec<f32>>
        let mut rows: Vec<Vec<f32>> = Vec::new();
        // push the first row
        rows.push(a);
        // push the second row
        rows.push(b);
        // now rows has exactly two elements,
        // and each push preserves the property
        rows
    }

    ///////// make_outer /////////////////////////////////////////////////
    // An alias for vstack, with the same spec.
    fn make_outer(a: Vec<f32>, b: Vec<f32>) -> (result: Vec<Vec<f32>>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == 2
            && result[0].len() == a.len()
            && result[1].len() == b.len()
            && forall |i: usize|
                 i < a.len() ==>
                    result[0][i] == a[i]
            && forall |i: usize|
                 i < b.len() ==>
                    result[1][i] == b[i]
    {
        vstack(a, b)
    }
}

